set-variable.value:
@{
        var jwt = (Jwt)context.Variables["jwt"];
        string[] v;
        if (jwt.Claims.TryGetValue("azp", out v) && v.Length > 0) { return v[0]; }
        if (jwt.Claims.TryGetValue("appid", out v) && v.Length > 0) { return v[0]; }
        return jwt.Subject;
    }

@{
            try
            {
                var body = context.Request.Body.As<JObject>(preserveContent: true);
                var model = body["model"];
                if (model == null || model.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)model)) { return "invalid"; }
                var alias = (string)model;
                if (alias != "fast-chat" && alias != "advanced-chat" && alias != "embeddings") { return "denied"; }
                if ((context.Operation.Id == "embeddings-create") != (alias == "embeddings")) { return "wrong-operation"; }
                return "allowed";
            }
            catch { return "invalid"; }
        }

when.set-body:
@{
            var body = context.Request.Body.As<JObject>(preserveContent: true);
            if (body["reasoning_effort"] == null)
            {
                body["reasoning_effort"] = (string)context.Variables["modelAlias"] == "fast-chat" ? "low" : "high";
            }
            return body.ToString(Newtonsoft.Json.Formatting.None);
        }

@{
            var raw = context.Request.Body.As<string>(preserveContent: true);
            try
            {
                var body = JObject.Parse(raw);
                var metadata = body["metadata"] as JObject ?? new JObject();
                metadata["gateway_caller"] = (string)context.Variables["caller"];
                metadata["gateway_model"] = (string)context.Variables["modelAlias"];
                body["metadata"] = metadata;
                return body.ToString(Newtonsoft.Json.Formatting.None);
            }
            catch { return raw; }
        }

when.condition:
@{
              var stored = context.Variables.GetValueOrDefault<IResponse>("storedResponse");
              if (stored == null || stored.StatusCode != 200) { return true; }
              try
              {
                  var body = stored.Body.As<JObject>(preserveContent: true);
                  return (string)body["metadata"]?["gateway_caller"] != (string)context.Variables["caller"]
                      || ((string)body["metadata"]?["gateway_model"] != "fast-chat" && (string)body["metadata"]?["gateway_model"] != "advanced-chat");
              }
              catch { return true; }
          }

set-variable.value:
@{
            try
            {
                var tokens = context.Response.Body.As<JObject>(preserveContent: true)["usage"]?["total_tokens"];
                if (tokens == null || tokens.Type != JTokenType.Integer) { return -1.0; }
                return (double)tokens;
            }
            catch { return -1.0; }
        }
